/* TODO 6: .judul font-size clamp(1.5rem, 4vw, 3rem) */

solution.css:
:root {
  --warna-utama: #1572b6;
  --jarak: 16px;
  --bg: #ffffff;
  --teks: #1a1a1a;
}

.tema-gelap {
  --bg: #121212;
  --teks: #f0f0f0;
}

body {
  margin: 0;
  font-family: system-ui, sans-serif;
}

.wadah {
  width: 400px;
}

.judul {
  font-size: clamp(1.5rem, 4vw, 3rem);
}

.kartu {
  color: var(--warna-utama);
  padding: var(--jarak);
}

.panel {
  padding: 12px;
  background: var(--bg);
  color: var(--teks);
}

.konten {
  width: calc(100% - 40px);
  background: #e8f0e0;
}
